function hex_to_str(string $hex): ?string
{
    if ($hex === '') {
        return '';
    }

    if (strlen($hex) % 2 !== 0 || !preg_match('/^[0-9a-fA-F]*$/', $hex)) {
        return null;
    }

    return hex2bin($hex);
}

