{
    $number = preg_replace('/[\s-]/', '', $number);

    if (!preg_match('/^[0-9]{2,}$/', $number)) {
        return false;
    }

    $sum = 0;
    $len = strlen($number);
    for ($i = 0; $i < $len; $i++) {
        $d = (int) $number[$i];
        if (($len - $i) % 2 === 0) {
