function sort_by_key(array $rows, string $key, string $order = 'asc'): array
{
    $indexed = [];
    $i = 0;
    foreach ($rows as $row) {
        $indexed[] = ['v' => $row[$key] ?? null, 'i' => $i, 'row' => $row];
        $i++;
    }

    usort($indexed, function ($a, $b) use ($order) {
        $cmp = $a['v'] <=> $b['v'];
        if ($order === 'desc') {
            $cmp = -$cmp;
        }
        if ($cmp !== 0) {
            return $cmp;
        }
        return $a['i'] <=> $b['i'];
    });

    $result = [];
    foreach ($indexed as $item) {
        $result[] = $item['row'];
    }

    return $result;
}

