function paginate_array(array $items, int $page, int $perPage): array
{
    if ($page < 1 || $perPage <= 0) {
        return [];
    }

    $offset = ($page - 1) * $perPage;
    if ($offset >= count($items)) {
        return [];
    }

    return array_slice($items, $offset, $perPage);
}

