function safe_int(mixed $value): ?int
{
    if (is_int($value)) {
        return $value;
    }

    if (is_float($value)) {
        return ($value == (int) $value) ? (int) $value : null;
    }

    if (is_string($value)) {
        $value = trim($value);
        if ($value === '') {
            return null;
        }
        if (preg_match('/^-?\d+$/', $value)) {
            return (int) $value;
        }
        return null;
    }

    return null;
}

