function mask_email(string $email): string
{
    $at = strpos($email, '@');
    if ($at === false) {
        return $email;
    }

    $local = substr($email, 0, $at);
    $domain = substr($email, $at);
    $len = strlen($local);

    if ($len <= 2) {
        return $email;
    }

    return $local[0] . str_repeat('*', $len - 2) . $local[$len - 1] . $domain;
}

