    for ($i = 0; $i < $len; $i++) {
        $d = (int) $number[$i];
        if (($len - $i) % 2 === 0) {
            $d *= 2;
            if ($d > 9) {
                $d -= 9;
            }
        }
        $sum += $d;
    }

    return $sum % 10 === 0;
}
